API Gateway & BFF.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway_bff, "API Gateway & BFF") {
    Component(GeoEnforcementRoutingProxy, "Geo-Enforcement & Routing Proxy", "Envoy Proxy", "Handles edge termination, TLS 1.3, regional geo-routing, rate limiting, and connection resilience.")
    Component(ConsentAuthMiddleware, "Consent & Auth Middleware", "Go", "Validates user authentication tokens and manages user consent policies.")
    Component(BFFAggregatorTransformer, "BFF Aggregator & Transformer", "Go", "Aggregates and transforms requests, routing them to downstream microservices.")
    Component(TelemetryResilienceInterceptor, "Telemetry & Resilience Interceptor", "Go", "Monitors rural network latencies, applies payload compression, circuit breaking, and distributed tracing.")
}

Rel(GeoEnforcementRoutingProxy, ConsentAuthMiddleware, "Forwards incoming traffic for token validation", "")
Rel(ConsentAuthMiddleware, BFFAggregatorTransformer, "Passes authenticated and authorized requests", "")
Rel(BFFAggregatorTransformer, TelemetryResilienceInterceptor, "Intercepts requests for tracing and resilience", "")

@enduml

Video Consultation Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Video Consultation Container container

Container_Boundary(video_consultation_container, "Video Consultation Container") {
    Component(WebRTC_SFU, "WebRTC SFU", "MediaSoup (C++)", "Powers the SFU media router for encrypted media handling (DTLS-SRTP).")
    Component(Signaling_Server, "Signaling Server", "Node.js & WebSockets", "Implements the Signaling Server and manages client signaling.")
    Component(Adaptive_Bitrate_Controller, "Adaptive Bitrate Controller", "Node.js", "Ensures reliable video consultations with adaptive bitrate down to 150 kbit/s for unstable connections.")
}

Rel(Signaling_Server, WebRTC_SFU, "Manages worker processes", "Local IPC")
Rel(Adaptive_Bitrate_Controller, WebRTC_SFU, "Adjusts media streams for unstable connections")
@enduml

Cloud Storage (WORM enabled).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Cloud Storage (WORM enabled) container

Container_Boundary("Cloud_Storage_WORM_enabled", "Cloud Storage (WORM enabled)") {
    Component("Object_Retention_Lock_Engine", "Object Retention Lock Engine", "Google Cloud Storage Object Retention Lock", "Enforces Write Once, Read Many (WORM) immutability policies for compliance and audit logs.")
    Component("CMEK_Key_Management_Module", "CMEK Key Management Module", "Cloud KMS", "Manages Customer-Managed Encryption Keys (CMEK) to secure regional data at rest.")
    Component("Storage_API_Interface", "Storage API Interface", "Google Cloud Storage APIs, HTTPS (REST)", "Handles asynchronous log ingestion requests and model retrieval queries from internal services.")
}

Rel("Storage_API_Interface", "Object_Retention_Lock_Engine", "Persists immutable logs")
Rel("Storage_API_Interface", "CMEK_Key_Management_Module", "Encrypts and decrypts stored objects")
@enduml
